#include "editor/EditorSession.hpp"
#include "assets/image/ImageCodec.hpp"
#include "assets/GltfLoader.hpp"
#include <algorithm>
#include <chrono>
#include <cmath>
#include <fstream>
#include <iostream>
#include <thread>
using namespace azurerender;
using Json=nlohmann::json;
namespace {
void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
Json apply(EditorSession& session,const std::string& operation,Json parameters=Json::object()){
    const auto result=session.edit(operation,std::move(parameters));if(!result)throw std::runtime_error(result.diagnostics.dump());return result.value;
}
Json wait(EditorSession& session,const std::string& task){
    const auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(15);
    while(std::chrono::steady_clock::now()<deadline){session.pollTasks();for(const auto& row:session.tasks().report())if(row.at("id")==task&&row.at("state")!="running")return row;std::this_thread::sleep_for(std::chrono::milliseconds(1));}
    throw std::runtime_error("Asset transfer task exceeded deadline");
}
}
int main(int argc,char** argv){if(argc!=4)return 2;const auto root=std::filesystem::temp_directory_path()/("azure-transfer-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));int status=0;
    try{
        Project::create(root,"Asset transfer");auto context=EditorContext::openProject(root/"project.azureproject");EditorSession session(context);
        const auto image=apply(session,"asset.import",{{"path",argv[1]}}).get<std::string>();apply(session,"document.save");
        const auto formats=apply(session,"asset.formats");bool found=false;for(const auto& format:formats)if(format.at("id")=="png"){require(format.at("write")&&format.contains("exportSettings"),"Format discovery exposes writer settings contracts");found=true;}require(found,"PNG is discoverable");
        const auto output=root/std::filesystem::u8path(u8"交换 🎨 图像");Json request={{"asset",image},{"format","png"},{"destination",output.u8string()},{"settings",Json::object()}};
        auto jpegRequest=request;jpegRequest["format"]="jpeg";jpegRequest["settings"]={{"quality",73}};jpegRequest["destination"]=(root/"jpeg-settings").u8string();
        const auto jpegPlan=apply(session,"asset.export-plan",jpegRequest);require(jpegPlan.at("settings").at("quality")==73,"Public planning accepts declared nonempty format settings");const auto jpegTask=apply(session,"asset.export",{{"plan",jpegPlan.at("plan")}}).at("task").get<std::string>();const auto jpegResult=wait(session,jpegTask);require(jpegResult.at("state")=="completed"&&jpegResult.at("result").at("quality")==73,"Public export applies declared nonempty format settings");
        jpegRequest["settings"]["unknown"]=true;require(!session.edit("asset.export-plan",jpegRequest),"Format validators reject unknown settings");jpegRequest["settings"]={{"quality",101}};require(!session.edit("asset.export-plan",jpegRequest),"Format validators reject out of range settings");jpegRequest["settings"]={{"quality",73}};jpegRequest["settingsVersion"]=2;require(!session.edit("asset.export-plan",jpegRequest),"Unsupported settings versions are rejected");
        auto unknownRequest=request;unknownRequest["unknown"]=true;require(!session.edit("asset.export-plan",unknownRequest),"Operation parameters retain strict unknown field rejection");
        const auto planned=apply(session,"asset.export-plan",request);require(planned.contains("plan")&&!std::filesystem::exists(output),"Public planning has no output side effect");
        auto task=apply(session,"asset.export",{{"plan",planned.at("plan")}}).at("task").get<std::string>();const auto complete=wait(session,task);require(complete.at("state")=="completed","Public export task completes");
        const auto published=std::filesystem::u8path(complete.at("result").at("output").get<std::string>());require(decodeImageFile(published).rgba8==decodeImageFile(std::filesystem::u8path(argv[1])).rgba8,"Public export preserves image samples");
        require(!session.edit("asset.export",{{"plan",planned.at("plan")}}),"Published plans are consumed exactly once");
        const auto conflict=apply(session,"asset.export-plan",request);task=apply(session,"asset.export",{{"plan",conflict.at("plan")}}).at("task");require(wait(session,task).at("state")=="failed","Task exposes output conflicts");
        const auto replacement=apply(session,"asset.export-plan",request);task=apply(session,"asset.export",{{"plan",replacement.at("plan")},{"replace",true}}).at("task");require(wait(session,task).at("state")=="completed","Explicit replacement supports retry");
        const auto stale=apply(session,"asset.export-plan",request);apply(session,"node.create",{{"id","changed"}});require(!session.edit("asset.export",{{"plan",stale.at("plan")}}),"Changed documents reject pending plans");require(!session.edit("asset.export-plan",request),"Unsaved documents protect transfer planning");apply(session,"document.save");
        request["destination"]=(root/"cancelled-output").u8string();const auto cancelled=apply(session,"asset.export-plan",request);task=apply(session,"asset.export",{{"plan",cancelled.at("plan")}}).at("task");apply(session,"tasks.cancel",{{"id",task}});require(wait(session,task).at("state")=="cancelled"&&!std::filesystem::exists(root/"cancelled-output"),"Public cancellation releases unpublished output");
        request["destination"]=(root/"edited-during-export").u8string();const auto edited=apply(session,"asset.export-plan",request);task=apply(session,"asset.export",{{"plan",edited.at("plan")}}).at("task");apply(session,"node.create",{{"id","during-export"}});require(wait(session,task).at("state")=="failed"&&!std::filesystem::exists(root/"edited-during-export"),"Document edits reject publication and release unpublished output");apply(session,"document.save");
        const auto sourceChanged=apply(session,"asset.export-plan",request);const auto imported=std::filesystem::u8path(sourceChanged.at("source").get<std::string>());std::ifstream originalFile(imported,std::ios::binary);const std::string originalBytes((std::istreambuf_iterator<char>(originalFile)),{});originalFile.close();{std::ofstream changedFile(imported,std::ios::binary|std::ios::app);changedFile.put('x');}require(!session.edit("asset.export",{{"plan",sourceChanged.at("plan")}}),"Changed source bytes invalidate pending plans");{std::ofstream restoredFile(imported,std::ios::binary|std::ios::trunc);restoredFile.write(originalBytes.data(),static_cast<std::streamsize>(originalBytes.size()));}
        const auto audio=apply(session,"asset.import",{{"path",argv[3]}}).get<std::string>();apply(session,"document.save");const auto audioPlan=apply(session,"asset.export-plan",{{"asset",audio},{"format","wav"},{"destination",(root/"converted-audio").u8string()},{"settings",{{"sampleRate",24000},{"channels",1}}}});task=apply(session,"asset.export",{{"plan",audioPlan.at("plan")}}).at("task");const auto audioResult=wait(session,task);require(audioResult.at("state")=="completed"&&audioResult.at("result").at("sampleRate")==24000&&audioResult.at("result").at("channels")==1,"Public audio export applies declared rate and channel settings");
        const auto model=apply(session,"asset.import",{{"path",argv[2]}}).get<std::string>();apply(session,"node.place",{{"resource",model},{"id","assembly"}});apply(session,"node.transform",{{"translation",{3,0,0}}});apply(session,"document.save");
        const auto tree=apply(session,"asset.export-plan",{{"node","assembly"},{"format","glb"},{"destination",(root/"subtree").u8string()}});task=apply(session,"asset.export",{{"plan",tree.at("plan")}}).at("task");const auto treeResult=wait(session,task);require(treeResult.at("state")=="completed","Selected subtree exports through public tasks");const auto loaded=loadGltfAsset(treeResult.at("result").at("output"));require(!loaded.vertices.empty()&&std::any_of(loaded.nodes.begin(),loaded.nodes.end(),[&](const auto& node){const auto index=static_cast<std::size_t>(&node-loaded.nodes.data());return node.name=="assembly"&&std::abs(loaded.nodeWorldMatrices.at(index)[12]-3)<1e-5F;}),"Selected subtree retains authored placement");
        apply(session,"node.create",{{"id","parent"}});apply(session,"node.transform",{{"translation",{10,0,0}}});apply(session,"node.reparent",{{"id","assembly"},{"parent","parent"}});apply(session,"node.select",{{"id","assembly"}});apply(session,"node.transform",{{"translation",{3,0,0}}});apply(session,"document.save");
        const auto nested=apply(session,"asset.export-plan",{{"node","assembly"},{"format","glb"},{"destination",(root/"nested-subtree").u8string()}});task=apply(session,"asset.export",{{"plan",nested.at("plan")}}).at("task");const auto nestedResult=wait(session,task);require(nestedResult.at("state")=="completed","Nested subtree generation completes");const auto nestedAsset=loadGltfAsset(nestedResult.at("result").at("output"));require(std::any_of(nestedAsset.nodes.begin(),nestedAsset.nodes.end(),[&](const auto& node){return node.name=="assembly"&&std::abs(nestedAsset.nodeWorldMatrices.at(static_cast<std::size_t>(&node-nestedAsset.nodes.data()))[12]-13)<1e-5F;}),"Selected subtree retains placement from ancestors outside the selection");
        const auto unicodeScene=root/std::filesystem::u8path(u8"场景 🎨.azscene");context->scene().save(unicodeScene);require(SceneDocument::load(unicodeScene).nodes.size()==context->scene().nodes.size(),"Native Unicode scene save and reload preserve nodes");const auto unicodeEditorScene=root/"assets"/std::filesystem::u8path(u8"编辑 🎨.azscene");std::filesystem::copy_file(root/"assets/startup.azscene",unicodeEditorScene);auto unicodeContext=EditorContext::openProject(root/"project.azureproject",unicodeEditorScene);EditorSession unicodeSession(unicodeContext);apply(unicodeSession,"node.create",{{"id","saved-unicode"}});apply(unicodeSession,"document.save");require(EditorContext::openProject(root/"project.azureproject",unicodeEditorScene)->scene().nodes.size()==context->scene().nodes.size()+1,"Editor save and recovery support Unicode document paths");
        const auto unicodeLevel=root/std::filesystem::u8path(u8"关卡 🎨.azurelevel");const auto level=Level::parse(Json{{"schemaVersion",1},{"id","unicode-level"},{"sceneType","sample"},{"resources",Json::array()},{"nodes",Json::array()}},context->assets());level.save(unicodeLevel);require(Level::load(unicodeLevel,context->assets()).scene.sceneId=="unicode-level","Native Unicode level save and reload preserve identity");
        std::cout<<"Public discovery, plan, export, retry, cancellation, stale rejection and subtree passed\n";
    }catch(const std::exception& error){std::cerr<<error.what()<<'\n';status=1;}
    std::filesystem::remove_all(root);return status;
}
